ACL_ACTIONS = frozenset(("allow", "drop", "remark_pcp"))
ACL_REMARK_ACTION = "remark_pcp"

MIN_ACL_VID = 0
MAX_ACL_VID = 4094
MIN_ACL_PCP = 0
MAX_ACL_PCP = 7


def _check_acl_action(value, path):
